import java.util.*;

class Solution {
    private static final int MOD = 1_000_000_007;
    private long modPow(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }
    public int maximumScore(List<Integer> nums, int k) {
        int n = nums.size();
        int maxV = 0;
        for (int v : nums) maxV = Math.max(maxV, v);
        int[] primeFactors = new int[maxV + 1];
        for (int i = 2; i <= maxV; i++) {
            if (primeFactors[i] == 0) {
                for (int j = i; j <= maxV; j += i) primeFactors[j]++;
            }
        }
        int[] scores = new int[n];
        for (int i = 0; i < n; i++) scores[i] = primeFactors[nums.get(i)];
        int[] left = new int[n];
        Arrays.fill(left, -1);
        int[] right = new int[n];
        Arrays.fill(right, n);
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && scores[stack.peek()] < scores[i]) stack.pop();
            if (!stack.isEmpty()) left[i] = stack.peek();
            stack.push(i);
        }
        stack.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && scores[stack.peek()] <= scores[i]) stack.pop();
            if (!stack.isEmpty()) right[i] = stack.peek();
            stack.push(i);
        }
        Integer[] items = new Integer[n];
        for (int i = 0; i < n; i++) items[i] = i;
        Arrays.sort(items, (a, b) -> Integer.compare(nums.get(b), nums.get(a)));
        long ans = 1;
        long remK = k;
        for (int i : items) {
            long count = (long) (i - left[i]) * (right[i] - i);
            long take = Math.min(remK, count);
            ans = (ans * modPow(nums.get(i), take)) % MOD;
            remK -= take;
            if (remK == 0) break;
        }
        return (int) ans;
    }
}

