var maximumScore = function(nums, k) {
    const MOD = 1000000007n;
    function modPow(base, exp) {
        let res = 1n;
        let b = BigInt(base) % MOD;
        let e = BigInt(exp);
        while (e > 0n) {
            if ((e & 1n) === 1n) res = (res * b) % MOD;
            b = (b * b) % MOD;
            e >>= 1n;
        }
        return res;
    }
    let maxV = 0;
    for (const v of nums) if (v > maxV) maxV = v;
    const primeFactors = new Array(maxV + 1).fill(0);
    for (let i = 2; i <= maxV; i++) {
        if (primeFactors[i] === 0) {
            for (let j = i; j <= maxV; j += i) primeFactors[j]++;
        }
    }
    const n = nums.length;
    const scores = nums.map(v => primeFactors[v]);
    const left = new Array(n).fill(-1);
    const right = new Array(n).fill(n);
    const stack = [];
    for (let i = 0; i < n; i++) {
        while (stack.length > 0 && scores[stack[stack.length - 1]] < scores[i]) stack.pop();
        if (stack.length > 0) left[i] = stack[stack.length - 1];
        stack.push(i);
    }
    stack.length = 0;
    for (let i = n - 1; i >= 0; i--) {
        while (stack.length > 0 && scores[stack[stack.length - 1]] <= scores[i]) stack.pop();
        if (stack.length > 0) right[i] = stack[stack.length - 1];
        stack.push(i);
    }
    const items = Array.from({ length: n }, (_, i) => i);
    items.sort((a, b) => nums[b] - nums[a]);
    let ans = 1n;
    let remK = BigInt(k);
    for (const i of items) {
        const count = BigInt(i - left[i]) * BigInt(right[i] - i);
        const take = remK < count ? remK : count;
        ans = (ans * modPow(nums[i], take)) % MOD;
        remK -= take;
        if (remK === 0n) break;
    }
    return Number(ans);
};
